# edm_prediction_interface ----
## Error handling ----
for (predictor_name in c("SimplexProjection", "SMapProjection", "GPEdmProjection")) {
  test_that(paste(predictor_name, "validates both embedding IDs before prediction"), {
    #' @description Every EDM predictor preserves invalid-ID and wrong-object-type errors for either or both arguments and succeeds after rejected inputs.
    clear()
    withr::defer(clear())
    library_embedding <- methods::new(DelayEmbedding)
    test_embedding <- methods::new(DelayEmbedding)
    series <- c(0.4, 0.9, 0.3, 0.8, 0.5, 0.7, 0.2, 0.6, 0.4, 0.9)
    library_embedding$construct(series, 2L, 1L, 1L)
    test_embedding$construct(series[5:10], 2L, 1L, 1L)
    predictor_class <- switch(predictor_name,
      SimplexProjection = SimplexProjection,
      SMapProjection = SMapProjection,
      GPEdmProjection = GPEdmProjection
    )
    predictor <- methods::new(predictor_class)
    predictor[["embedding_dimension"]] <- 2L
    library_id <- library_embedding$get_id()
    test_id <- test_embedding$get_id()
    wrong_type_id <- predictor$get_id()
    context <- paste0(predictor_name, "Interface::predict: ")
    invalid_message <- paste0(context, "invalid lib_id or test_id.")
    wrong_type_message <- paste0(
      context, "live objects are not of type DelayEmbeddingInterface."
    )
    for (ids in list(
      c(0L, test_id), c(library_id, 0L), c(0L, 0L), c(wrong_type_id, 0L)
    )) {
      expect_error(
        predictor$predict(ids[[1L]], ids[[2L]]),
        invalid_message,
        fixed = TRUE
      )
    }
    for (ids in list(
      c(wrong_type_id, test_id),
      c(library_id, wrong_type_id),
      c(wrong_type_id, wrong_type_id)
    )) {
      expect_error(
        predictor$predict(ids[[1L]], ids[[2L]]),
        wrong_type_message,
        fixed = TRUE
      )
    }
    predictions <- predictor$predict(library_id, test_id)
    expect_type(predictions, "double")
    expect_length(predictions, test_embedding[["n_rows"]])
    expect_true(all(is.finite(predictions)))
    expect_identical(predictor$predict(library_id, test_id), predictions)
    self_predictions <- predictor$predict(library_id, library_id)
    expect_length(self_predictions, library_embedding[["n_rows"]])
    expect_true(all(is.finite(self_predictions)))
  })
}
